const {deviceState,syncDevice}=require('../../utils/page')
const {fetchCatalogue,MODULES}=require('./ieltsPaperService')
const {fetchCatalogue:fetchAudioCatalogue}=require('./ieltsAudioService')
const {tracksForPaper}=require('./ieltsPaperAudio')
const {createAudioDownloadController}=require('./audioDownload')
const {createPdfDownloadController,initialPdfDownloadState,formatBytes}=require('../../utils/pdfDownload')
const {refreshNativeSession}=require('../../utils/nativeSession')
Page({
 ...require('../../utils/share').public,
 onShareAppMessage(){return{title:'STEMist · 剑雅真题、答案与音频',path:'/bundles/curricula/ieltsPapers',imageUrl:'/design-system/share-card.png'}},
 data:deviceState({loading:true,error:'',audioLoading:true,audioError:'',audioOffline:false,hasListening:false,books:[],book:0,bookIndex:0,module:'',modules:[{id:'',label:'全部'},...Object.entries(MODULES).map(([id,label])=>({id,label}))],items:[],total:0,page:0,pages:0,pdfPreparing:false,pdfDownload:initialPdfDownloadState(),audioDownload:{itemId:'',active:false,sharing:false,ready:false,progress:null,error:''}}),
 onLoad(options={}){this.__disposed=false;this.__generation=0;this.__audioGeneration=0;this.setData({book:Number(options.book)||0,module:MODULES[options.module]?options.module:''});this.__pdf=createPdfDownloadController({wxApi:wx,isScopeCurrent:scope=>!this.__disposed&&scope===this.scope(),onState:state=>{if(!this.__disposed)this.setData({pdfDownload:state})}});this.__audioDownload=createAudioDownloadController({onState:audioDownload=>{if(!this.__disposed)this.setData({audioDownload})}});return this.load()},
 scope(){return[this.data.book,this.data.module,this.data.page].join('|')},
 onShow(){syncDevice(this);this.__pdf?.setScope(this.scope());this.__audioDownload?.setScope(this.scope());this.__pdf?.resume()},onResize(){syncDevice(this)},onHide(){this.__pdf?.suspend();this.__audioDownload?.suspend()},onUnload(){this.__disposed=true;this.__generation++;this.__audioGeneration++;this.__pdf?.dispose();this.__audioDownload?.dispose()},
 locked(){return this.__opening||this.data.pdfDownload.active||this.data.audioDownload.active||this.data.audioDownload.sharing},
 async load(){if(this.locked())return;const generation=++this.__generation;this.setData({loading:true,error:''});const audioWork=this.loadAudioCatalogue();try{const c=await fetchCatalogue();if(this.__disposed||generation!==this.__generation)return;this.__catalogue=c;const books=c.books.map(value=>({value,label:'Cambridge '+value})),book=books.some(b=>b.value===this.data.book)?this.data.book:books[0]?.value||0;this.setData({books,book,bookIndex:Math.max(0,books.findIndex(b=>b.value===book)),page:0});this.render()}catch(e){if(!this.__disposed&&generation===this.__generation)this.setData({error:e.message})}finally{if(!this.__disposed&&generation===this.__generation)this.setData({loading:false})}await audioWork},
 async loadAudioCatalogue(){const generation=++this.__audioGeneration;this.setData({audioLoading:true,audioError:''});try{const c=await fetchAudioCatalogue();if(this.__disposed||generation!==this.__audioGeneration)return;this.__audioCatalogue=c;this.setData({audioOffline:!!c.offline});this.render()}catch(e){if(!this.__disposed&&generation===this.__audioGeneration){this.__audioCatalogue=null;this.setData({audioError:'音频目录暂时无法读取，请重试。',audioOffline:false});this.render()}}finally{if(!this.__disposed&&generation===this.__audioGeneration)this.setData({audioLoading:false})}},
 retryAudioCatalogue(){if(!this.locked())return this.loadAudioCatalogue()},
 render(){
  const list=(this.__catalogue?.items||[]).filter(i=>(!this.data.book||i.book===this.data.book)&&(!this.data.module||i.module===this.data.module)),pages=Math.ceil(list.length/12),page=Math.min(this.data.page,Math.max(0,pages-1)),scope=[this.data.book,this.data.module,page].join('|')
  this.__pdf?.setScope(scope);this.__audioDownload?.setScope(scope)
  const items=list.slice(page*12,page*12+12).map(i=>{const audioTracks=tracksForPaper(i,this.__audioCatalogue?.items).map(a=>({...a,trackLabel:a.trackCount===1?'完整音频':'音频 '+a.track+' / '+a.trackCount,sizeLabel:formatBytes(a.bytes)}));return{...i,qpMeta:i.qp.pages+' 页 · '+formatBytes(i.qp.bytes),akMeta:i.ak?i.ak.pages+' 页 · '+formatBytes(i.ak.bytes):'',answerNote:i.ak?'':i.answerStatus==='no_unique_answer'?'写作、口语没有唯一标准答案。':'参考答案尚有缺项，暂不提供下载。',audioTracks,audioPartial:audioTracks.length>0&&audioTracks.length<audioTracks[0].trackCount}})
  this.setData({page,pages,total:list.length,items,hasListening:items.some(i=>i.module==='listening')})
 },
 chooseBook(e){if(this.locked())return;const index=Number(e.detail.value),book=this.data.books[index];if(!book)return;this.setData({book:book.value,bookIndex:index,page:0});this.render()},
 chooseModule(e){if(this.locked())return;const module=String(e.currentTarget.dataset.module||'');if(module&&!MODULES[module])return;this.setData({module,page:0});this.render()},
 previous(){if(!this.locked()&&this.data.page>0){this.setData({page:this.data.page-1});this.render();wx.pageScrollTo?.({scrollTop:0,duration:0})}},next(){if(!this.locked()&&this.data.page+1<this.data.pages){this.setData({page:this.data.page+1});this.render();wx.pageScrollTo?.({scrollTop:0,duration:0})}},
 async openPdf(e){if(this.locked())return;const group=this.data.items.find(i=>i.id===e.currentTarget.dataset.id),kind=e.currentTarget.dataset.kind==='ak'?'ak':'qp',file=group?.[kind];if(!file)return;if(!wx.getStorageSync('stemistUser')?.id){this.account();return}const scope=this.scope(),owner=String(wx.getStorageSync('stemistUser')?.id),epoch=wx.getStorageSync('stemistPrivacyEpoch');this.__opening=true;this.setData({pdfPreparing:true});try{await refreshNativeSession();if(this.__disposed||scope!==this.scope()||owner!==String(wx.getStorageSync('stemistUser')?.id)||epoch!==wx.getStorageSync('stemistPrivacyEpoch'))return;this.__pdf.setScope(scope);return await this.__pdf.open({url:file.url,cacheKey:file.sha256,cacheVersion:file.sha256,cacheScope:'identity',ownerKey:file.id,itemId:group.id,label:group.meta+' · '+(kind==='ak'?'参考答案':'题目'),fileName:file.fileName,expectedBytes:file.bytes,sha256:file.sha256,scope})}catch(e){if(!this.__disposed)this.setData({error:e.message})}finally{this.__opening=false;if(!this.__disposed)this.setData({pdfPreparing:false})}},
 downloadAudio(e){if(this.locked())return;const group=this.data.items.find(i=>i.id===e.currentTarget.dataset.id),item=group?.audioTracks.find(a=>a.id===e.currentTarget.dataset.audioId);if(!item)return;if(!wx.getStorageSync('stemistUser')?.id){this.account();return}return this.__audioDownload.download(item)},
 shareAudio(){if(!this.locked())return this.__audioDownload?.share()},cancelAudio(){this.__audioDownload?.cancel()},retryAudio(){if(!this.locked())return this.__audioDownload?.retry()},
 cancel(){this.__pdf?.cancel()},retry(){if(!this.locked())return this.__pdf?.retry()},toggle(){this.__pdf?.toggleCollapsed()},account(){wx.navigateTo({url:'/pages/account/auth'})},back(){wx.navigateBack({fail:()=>wx.reLaunch({url:'/pages/practice/index?category=ielts'})})},
})
